import { test, expect } from 'vitest';
import { page } from 'vitest/browser';
import { renderFileList } from './file-list.js';

test('deletes the selected files', async () => {
  const container = document.createElement('div');
  document.body.append(container);
  renderFileList(container, ['a.txt', 'b.txt', 'c.txt']);

  await page.getByRole('checkbox', { name: 'a.txt' }).click();
  await page.getByRole('checkbox', { name: 'b.txt' }).click();
  await page.getByRole('button', { name: /^Delete\b/ }).click();

  const items = page.getByRole('listitem');
  await expect.poll(() => items.elements().map((li) => li.querySelector('span').textContent)).toEqual(['c.txt']);

  container.remove();
});

